        render(
            <DiagramComparisonLayout
                horizontalComparison={<div>Horizontal comparison</div>}
                layoutService={layoutService}
                tabbedComparison={<div>Tabbed comparison</div>}
                verticalComparison={<div>Vertical comparison</div>}
